const body = $input.all()[0].json.body;
const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const now = new Date();
// Ajuste para Fuso Horário BR (-4)
now.setHours(now.getHours() - 4);
const msgData = body.data;
const remoteJid = msgData.key.remoteJid;
const isGroup = remoteJid.includes('@g.us');
if (isGroup) { throw new Error('Ignorar Grupos'); }
// Detecta se é áudio ou texto
const messageType = msgData.messageType;
const textMessage = msgData.message?.conversation || msgData.message?.extendedTextMessage?.text || "";
return {
  day_of_week: days[now.getDay()],
  hour: now.getHours(),
  phone: remoteJid.replace('@s.whatsapp.net', ''),
  pushName: msgData.pushName,
  messageType: messageType, // Importante para o Switch
  text: textMessage
};

