const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const ptDays = {
    'Monday': 'Segunda-feira',
    'Tuesday': 'Terca-feira',
    'Wednesday': 'Quarta-feira',
    'Thursday': 'Quinta-feira',
    'Friday': 'Sexta-feira',
    'Saturday': 'Sabado',
    'Sunday': 'Segunda-feira' // Fallback for Sunday
};

// Determine TODAY and TOMORROW manually to force the LLM to get it right
const now = new Date();
now.setHours(now.getHours() - 4); // Adjust for BRT-ish (mock)

const todayIndex = now.getDay();
const todayName = days[todayIndex];
const today_pt = ptDays[todayName];

// Date Formatting (DD/MM/YYYY)
const formattedDateToday = now.toLocaleDateString('pt-BR');

// Calculate Tomorrow
const tomorrowDate = new Date(now);
tomorrowDate.setDate(now.getDate() + 1);
const tomorrowIndex = tomorrowDate.getDay();
const tomorrowName = days[tomorrowIndex];
const tomorrow_pt = ptDays[tomorrowName];
const formattedDateTomorrow = tomorrowDate.toLocaleDateString('pt-BR');

// Calculate Time
const hours = now.getHours().toString().padStart(2, '0');
const minutes = now.getMinutes().toString().padStart(2, '0');
const currentTime = `${hours}:${minutes}`;

// Get user message
const mergeNode = $input.all()[0] ? $input.all()[0].json : {};
const userText = mergeNode.text || mergeNode.textMessage || "";
const contextNode = $('Filtro e Contexto').first().json;

// Helper to build menu string
function buildMenuString(key) {
    let str = "";
    if (menuData.cardapio.CardapioSemanal[key]) {
        // str += `Cardápio de ${key}:\n`; // header removed to be cleaner in prompt
        menuData.cardapio.CardapioSemanal[key].forEach(item => {
            if (item.opcao) {
                str += `- ${item.opcao}: ${item.prato} (Acomp: ${item.acompanhamentos})\n`;
            }
        });
        if (menuData.cardapio.CardapioSemanal[key].length > 0) {
             const info = menuData.cardapio.CardapioSemanal[key].find(i => i.info_extra);
             if (info) str += `\n${info.info_extra}`;
        }
    } else {
        str = `Não há cardápio específico para ${key}.`;
    }
    return str;
}

// Build Shortcut Menus
const menuToday = buildMenuString(today_pt);
const menuTomorrow = buildMenuString(tomorrow_pt);

// Build FULL Weekly Context
let fullMenuContext = "";
const orderedDays = ['Segunda-feira', 'Terca-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira', 'Sabado'];

orderedDays.forEach(dayName => {
    fullMenuContext += `--- ${dayName} ---\n` + buildMenuString(dayName) + "\n\n";
});

// Build Extras/Bebidas Context
let bebidasContext = "Bebidas:\n";
menuData.cardapio.Bebidas.forEach(b => {
    bebidasContext += `- ${b.nome}: ${b.preco}\n`;
});
bebidasContext += "\nSobremesas:\n";
menuData.cardapio.Sobremesas.forEach(s => {
    bebidasContext += `- ${s.nome}: ${s.preco}\n`;
});

// Build Cliente Context
let clienteContext = "Dados do Cliente:\n";
if (contextNode.pushName) {
    clienteContext += `Nome: ${contextNode.pushName}\n`;
} else {
    clienteContext += "Cliente Novo (sem cadastro VIP identified)";
}

return {
    fullMenuContext,
    menuToday,
    menuTomorrow,
    bebidasContext,
    clienteContext,
    mensagemUsuario: userText,
    today_pt,
    tomorrow_pt,
    currentTime,
    formattedDateToday,
    formattedDateTomorrow
};
